package ads.poo;

import java.util.ArrayList;
import java.util.Arrays;

public class App {

    public static void main(String[] args) {
        ArrayList<Disciplina> disciplinas = new ArrayList<>();

        Disciplina poo = new Disciplina(new DiaDaSemana[]{DiaDaSemana.TERCA, DiaDaSemana.QUARTA}, "POO");
        Disciplina fei = new Disciplina(new DiaDaSemana[]{DiaDaSemana.TERCA, DiaDaSemana.SEXTA}, "FEI");

        disciplinas.add(poo);
        disciplinas.add(fei);

        for(Disciplina disciplina : disciplinas){
            if(Arrays.asList(disciplina.getDias()).contains(DiaDaSemana.QUARTA)){
                IO.println(disciplina);
            }

            for(DiaDaSemana diaDaSemana : disciplina.getDias()){
                if(diaDaSemana.equals(DiaDaSemana.QUARTA)){
                    IO.println(disciplina);
                }
            }
        }
    }
}
